window.RP_SESSION={"id":"S-2bba5bdc61bb","messages":[{"id":"RP-II-0201539","time":"2026-09-21T23:42:00+09:00","room":"RP II","name":"지크","profile":"발린 호프","identity":"reviewed","type":"dialogue","body":"\"....\"\n\n루체를 찾으러 갔다가 돌아오자마자 모닥불 붙이는 지크입니다.","characters":["P-b918def3d6d3"]},{"id":"RP-II-0201540","time":"2026-09-22T00:09:00+09:00","room":"RP II","name":"지크","profile":"발린 호프","identity":"reviewed","type":"dialogue","body":"불쏘시게로 붉어진 장작들을 툭툭 건드리는 지크.\n\n그럴때 마다 장작에서 나오는 작은 뿔씨들이 지크의 얼굴뼈 쪽에 닿고는 치이익- 하는 소리와 함께 식어 거뭇해집니다.\n\n최근 방안에서 나오자 소식들이 많이 들려왔습니다.\n\n아도니스가 숲속으로 떠나돌아오지 않고있다는 사실\n아서가 의뢰중 고립되었다는 사실.\n다른길드로 인원들이 파견된다는 사실.\n\n그중 하나는 직접 지원도 했습니다.\n결과적으론 떨어졌지만 말이죠..\n\n허나 나쁘지 않은 수확들과 정보들의 연속이라 지크는 스스로 생각합니다.\n\n그러면서 자신의 앙상한 손를 뒷통수쪽으로 가져다 대 손깍지를 끼었죠.\n\n허나 왜일까요.\n\n아무것도 느껴지지 않아야 할 가슴 안쪽이 무거운 쇳덩이라도 달린것마냥 아래로 꺼지는 감각은.\n\n분명 평화로운데 분명 안정적이라고 느껴지는 제 2의 삶인데\n\n왜이리 항상 불언하다고 여기는것일까요.\n\n역설적이게도 지크는 지금 죄책감을 느끼고 있었습니다\n\n자신 스스로만 평화롭고 안정적이라는 죄책감에.\n\n그는 생전 미련이 없습","characters":["P-b918def3d6d3"]},{"id":"RP-II-0201541","time":"2026-09-22T00:11:00+09:00","room":"RP II","name":"지크","profile":"발린 호프","identity":"reviewed","type":"dialogue","body":"지크는 불쏘시게를 장장을 탁- 짚습니다\n\n그러자 굵직한 불씨가 한번 튀죠.\n\n\"하아...내일은..무슨 소식이 들려오려나..\"","characters":["P-b918def3d6d3"]},{"id":"RP-II-0201542","time":"2026-09-22T00:11:00+09:00","room":"RP II","name":"지크","profile":"발린 호프","identity":"reviewed","type":"dialogue","body":"-fin","characters":["P-b918def3d6d3"]},{"id":"RP-II-0201543","time":"2026-09-22T00:11:00+09:00","room":"RP II","name":"판정·진행 봇","profile":"《운명의 굴레》","identity":"bot","type":"bot","body":"\"아주 멋진 한판이었어!\"","characters":[]}]};
